+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

+const STORE_PATH = process.env.SESSION_STORE_PATH || ".sessions";
+
 const store = new Map<string, Entry>();
+let initialized = false;
+
+const ensureDir = (): void => {
+  if (!fs.existsSync(STORE_PATH)) {
+    fs.mkdirSync(STORE_PATH, { recursive: true });
+  }
+};
+
+const getFilePath = (key: string): string => {
+  return path.join(STORE_PATH, `${encodeURIComponent(key)}.json`);
+};
+
+const loadFromDisk = (): void => {
+  ensureDir();
+  try {
+    const files = fs.readdirSync(STORE_PATH);
+    for (const file of files) {
+      if (!file.endsWith(".json")) continue;
+      try {
+        const filePath = path.join(STORE_PATH, file);
+        const data = JSON.parse(fs.readFileSync(filePath, "utf-8"));
+        const key = decodeURIComponent(file.slice(0, -5));
+        if (data.expiresAt > Date.now()) {
+          store.set(key, data);
+        } else {
+          fs.unlinkSync(filePath);
+        }
+      } catch {
+        // Skip corrupted files
+      }
+    }
+  } catch {
+    // Directory doesn't exist yet; will be created on first write
+  }
+  initialized = true;
+};
+
+const persistToDisk = (key: string, entry: Entry): void => {
+  ensureDir();
+  const filePath = getFilePath(key);
+  fs.writeFileSync(filePath, JSON.stringify(entry), "utf-8");
+};
+
+const deleteFromDisk = (key: string): void => {
+  const filePath = getFilePath(key);
+  try {
+    fs.unlinkSync(filePath);
+  } catch {
+    // File doesn't exist; no-op
+  }
+};

 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  if (!initialized) loadFromDisk();
+  const entry = { value, expiresAt: Date.now() + ttlMs };
+  store.set(key, entry);
+  persistToDisk(key, entry);
 };

 export const get = (key: string): string | null => {
+  if (!initialized) loadFromDisk();
   const entry = store.get(key);
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    deleteFromDisk(key);
     return null;
   }
   return entry.value;
